[CmdletBinding()]
param([string]$ProjectRoot=(Get-Location).Path,[string]$ManifestPath='',[switch]$RequireManifest,[switch]$SkipPathExistence)
$ErrorActionPreference='Stop'; $repoRoot=Split-Path -Parent $PSScriptRoot; $errors=[System.Collections.Generic.List[string]]::new()
function Read-Yaml([string]$Path){$code="import sys,yaml,json,pathlib; print(json.dumps(yaml.safe_load(pathlib.Path(sys.argv[1]).read_text(encoding=chr(117)+chr(116)+chr(102)+chr(45)+chr(56))), ensure_ascii=False, default=str))";$o=& python -c $code $Path 2>&1;if($LASTEXITCODE-ne 0){throw "Cannot parse YAML: $Path`n$($o-join"`n")"};return ($o-join"`n")|ConvertFrom-Json}
$rootPath=(Resolve-Path -LiteralPath $ProjectRoot).Path;if([string]::IsNullOrWhiteSpace($ManifestPath)){$ManifestPath=Join-Path $rootPath '.spec/manifest.yaml'}elseif(-not [IO.Path]::IsPathRooted($ManifestPath)){$ManifestPath=Join-Path $rootPath $ManifestPath}
if(-not(Test-Path -LiteralPath $ManifestPath -PathType Leaf)){if($RequireManifest){Write-Error "manifest not found: $ManifestPath";exit 1};Write-Output "Artifact manifest validation skipped: no manifest at $ManifestPath";exit 0}
try{$manifest=Read-Yaml $ManifestPath;$registry=Read-Yaml (Join-Path $repoRoot 'governance/artifact-registry.yaml')}catch{Write-Error $_;exit 1}
if([string]::IsNullOrWhiteSpace([string]$manifest.projectId)){$errors.Add('manifest.projectId is required')};$lifecycles=@('CREATE','CHANGE','DEFECT','REFACTOR','INCIDENT','OPTIMIZE');$defs=@{};foreach($d in @($registry.artifacts)){if($d-and $d.type){$defs[[string]$d.type]=$d}}
$items=@($manifest.artifacts);if($items.Count-eq 0){$errors.Add('manifest.artifacts is empty')};$ids=[System.Collections.Generic.HashSet[string]]::new()
foreach($a in $items){$type=[string]$a.type;$d=$defs[$type];$req=if($d-and $d.required){@($d.required)}else{@('artifactId','type','path','lifecycle','owner','status','producedBy','producedAt')};foreach($f in $req){if($null-eq $a.$f-or [string]::IsNullOrWhiteSpace([string]$a.$f)){$errors.Add("artifact missing required field: $f")}};$id=[string]$a.artifactId;if($id-and -not $ids.Add($id)){$errors.Add("duplicate artifactId: ${id}")};if(-not $d){$errors.Add("unknown artifact type: ${type}")};$lc=[string]$a.lifecycle;if($lc-notin $lifecycles){$errors.Add("invalid lifecycle for ${id}: ${lc}")};$statuses=if($d-and $d.statuses){@($d.statuses)}else{@('DRAFT','REVIEW','APPROVED','SUPERSEDED')};$status=[string]$a.status;if($status-notin $statuses){$errors.Add("invalid status for ${id}: ${status}")};$path=[string]$a.path;if([IO.Path]::IsPathRooted($path)-or $path-match '(^|[\\/])\.\.([\\/]|$)'){$errors.Add("artifact path must stay inside project: ${id} -> ${path}")};if(-not $SkipPathExistence-and $path-and -not(Test-Path -LiteralPath(Join-Path $rootPath $path))){$errors.Add("artifact path does not exist: ${id} -> ${path}")}}
if($errors.Count-gt 0){$errors|%{Write-Error $_};Write-Output "Artifact manifest validation failed: $($errors.Count) error(s)";exit 1};Write-Output "Artifact manifest validation passed: $($items.Count) artifact(s)";exit 0